const { buildGraph } = require('../core/graph');
const model = require('../core/model');

const mk = (root, kids) => { const m = model.newMap ? model.newMap(root) : null; return m; };

test('peso da rede: tópico muito citado pesa mais que um isolado e é determinístico', () => {
  const nodes = (titles) => titles.map((t) => ({ id: t, title: t, notes: '', children: [], markers: [], progress: null }));
  const mapOf = (title, notesByTitle) => {
    const kids = nodes(['A', 'B', 'C', 'Hub']).map((k) => ({ ...k, notes: notesByTitle[k.title] || '' }));
