/** Peças pequenas da tela inicial: cada uma recebe só o que precisa (dados + ações), sem tocar em estado global. */

/** Quando o arquivo foi mexido pela última vez, em palavras curtas. */
export const ago = (ms) => {
  if (!ms) return '';
  const d = Math.floor((Date.now() - ms) / 86400000);
  return d <= 0 ? 'hoje' : d === 1 ? 'ontem' : d < 30 ? `há ${d} dias` : new Date(ms).toLocaleDateString('pt-BR');
};

/** Botão grande de ação da coluna da esquerda. */
export function ActionButton({ id, title, hint, primary, onClick }) {
  return (
    <button className={'hm-action' + (primary ? ' primary' : '')} id={id} onClick={onClick}>
      <b>{title}</b><span>{hint}</span>
    </button>
  );
}

/** "Continuar de onde parou": o último mapa que ainda existe. */
export function ContinueCard({ last, onOpen }) {
  return (
    <section className="hm-sec hm-continue-sec" id="hmLast">
      <h3>Continuar de onde parou</h3>
      <button className="hm-continue" id="hmContinue" onClick={() => onOpen(last)}>
        <b>{last.name}</b>
        <span className="muted">{last.dir} · {ago(last.mtime)}</span>
      </button>
    </section>
  );
}

/** Cartão de um mapa recente; o × só tira da lista (o arquivo não é apagado). */
export function RecentCard({ item, onOpen, onRemove }) {
  return (
    <li className={'hm-card' + (item.exists ? '' : ' missing')}>
      <button className="hm-card-open" disabled={!item.exists} onClick={() => onOpen(item)} title={item.path}>
        <b>{item.name}</b>
        <span className="muted">{item.exists ? `${item.dir}` : 'arquivo não encontrado'}</span>
        <span className="hm-card-when">{item.exists ? ago(item.mtime) : ''}</span>
      </button>
      <button className="icon-btn sm hm-card-x" title="Tirar da lista (o arquivo não é apagado)" aria-label={'Tirar da lista: ' + item.name} onClick={() => onRemove(item.path)}>×</button>
    </li>
  );
}
EOF
cat > renderer/react/Home.jsx <<'EOF'
import { useState } from 'react';
import { H } from './hooks.js';
import { ActionButton, ContinueCard, RecentCard } from './home-parts.jsx';

/** Tela inicial: à esquerda, o que fazer agora; à direita, de onde parou e os mapas recentes em cartões. */
export function Home() {
  const [data, setData] = useState(() => H().homeData());
  const A = H().homeActions;
  const refresh = () => setData(H().homeData());
  const remove = async (p) => { await A.removeRecent(p); refresh(); };
  const clear = async () => { await A.clearRecent(); refresh(); };
  return (
    <div className="hm">
      <div className="hm-start">
        <div className="hm-brand">
          <img className="hm-logo" src="assets/logo.svg" alt="" height="40" />
          <h1>BRANIAC</h1>
        </div>
        <p className="hm-lead">Seu grande cérebro para mapas mentais. Abre e salva no formato do Mindomo.</p>
        <div className="hm-actions">
          <ActionButton id="hmNew" primary title="Novo mapa" hint="Começa com a ideia central e três tópicos" onClick={() => A.newBlank()} />
          <ActionButton id="hmOpen" title="Abrir arquivo .mom" hint="Um mapa do Mindomo ou salvo aqui" onClick={() => A.openFile()} />
          <ActionButton id="hmPdf" title="Ler um PDF" hint="Selecione um trecho para virar tópico" onClick={() => A.openPdf()} />
          <ActionButton id="hmDash" title="Painel de mapas" hint="Resumo dos seus mapas" onClick={() => H().openDash()} />
        </div>
      </div>

      <div className="hm-main">
        {data.last && <ContinueCard last={data.last} onOpen={A.openRecent} />}
        <section className="hm-sec" id="hmRecent">
          <h3>
            <span>Mapas recentes</span>
            {data.recent.length > 0 && <button className="link" id="hmClear" onClick={clear}>limpar lista</button>}
          </h3>
          {data.recent.length === 0 && (
            <div className="empty">Nenhum mapa aberto ainda. Crie um novo ou arraste um arquivo .mom para esta janela.</div>
          )}
          <ul className="hm-cards">
            {data.recent.map((r) => <RecentCard key={r.path} item={r} onOpen={A.openRecent} onRemove={remove} />)}
          </ul>
        </section>
      </div>
    </div>
  );
}
EOF
